INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (12, 'Hasil potongan kain tidak lurus', 'Garis potong menyimpang atau tepi kain tidak mengikuti pola yang diinginkan.', 'Pisau kurang tajam, teknik pengoperasian kurang stabil, atau lapisan kain tidak tertata dengan baik.', 'Periksa ketajaman pisau dan rapikan susunan lapisan kain. Gunakan gerakan pemotongan yang stabil mengikuti garis pola.', 'Matikan mesin sebelum memeriksa atau mengganti pisau.', 'Data spesifikasi KS-AUV dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (12, 'Pisau tidak tajam atau hasil potongan kasar', 'Tepi kain terlihat kasar, berbulu, atau pisau sulit memotong lapisan kain.', 'Ketajaman pisau menurun atau sistem automatic sharpening tidak bekerja optimal.', 'Periksa sistem automatic sharpening dan lakukan pengasahan sesuai kebutuhan. Pastikan pisau terpasang dengan benar.', 'Matikan mesin dan lepaskan sumber listrik sebelum memeriksa area pisau atau sistem pengasah.', 'Data spesifikasi automatic sharpening KS-AUV');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (12, 'Kapasitas potong tidak tercapai', 'Mesin sulit memotong jumlah lapisan kain yang biasanya dapat dipotong.', 'Ketajaman pisau menurun, jenis atau ketebalan material terlalu berat, atau ukuran pisau tidak sesuai kebutuhan.', 'Periksa kondisi pisau dan pilih ukuran pisau yang sesuai. Jangan memaksakan kapasitas pemotongan di luar rentang spesifikasi 110–290 mm.', 'Jangan menambah tekanan secara paksa pada mesin saat memotong material.', 'Data spesifikasi cutting capacity dan knife options KS-AUV');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (12, 'Pisau bergerak tidak normal', 'Gerakan pisau vertikal tersendat, bergetar, atau tidak stabil saat mesin beroperasi.', 'Mekanisme pisau mengalami gangguan, terdapat kotoran, atau bagian penggerak memerlukan pemeriksaan.', 'Hentikan mesin dan periksa area mekanisme pisau dari kotoran atau hambatan. Periksa gerakan vertikal pisau sebelum digunakan kembali.', 'Matikan mesin dan lepaskan sumber listrik sebelum memeriksa mekanisme pisau.', 'Data spesifikasi cutting method vertical straight knife KS-AUV');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (12, 'Motor tidak berputar atau putaran tidak stabil', 'Mesin tidak menyala, motor berhenti, atau putaran motor berubah-ubah saat digunakan.', 'Gangguan pada sumber listrik 220 V, sambungan listrik, atau motor 500 W.', 'Periksa sumber listrik, kabel, dan sambungan daya. Jika kelistrikan normal tetapi motor tetap bermasalah, lakukan pemeriksaan motor.', 'Pastikan sumber listrik diputus sebelum memeriksa kabel atau bagian kelistrikan.', 'Data spesifikasi motor 500 W dan power supply 220 V KS-AUV');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (12, 'Pelumasan tidak normal', 'Gerakan mekanis terasa kasar, suara meningkat, atau bagian bergerak tidak lancar.', 'Sistem automatic lubrication tidak bekerja normal atau kondisi pelumasan tidak sesuai.', 'Periksa sistem pelumasan otomatis dan pastikan bagian yang membutuhkan pelumasan mendapatkan suplai sesuai sistem mesin.', 'Matikan mesin sebelum memeriksa atau melakukan perawatan pelumasan.', 'Data spesifikasi automatic lubrication KS-AUV');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (12, 'Pisau cepat aus atau rusak', 'Pisau cepat kehilangan ketajaman atau mengalami kerusakan selama pemotongan.', 'Material tidak sesuai, pisau digunakan di luar kondisi yang sesuai, atau sistem sharpening tidak disetel dengan benar.', 'Periksa jenis material, kondisi pisau, dan sistem automatic sharpening. Gunakan ukuran pisau yang sesuai dengan pekerjaan.', 'Jangan menyentuh pisau saat mesin masih terhubung ke sumber listrik.', 'Data spesifikasi knife options dan automatic sharpening KS-AUV');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (12, 'Mesin sulit dikendalikan saat memotong', 'Gerakan mesin terasa berat atau kurang stabil sehingga hasil potongan sulit dikontrol.', 'Susunan lapisan kain tidak stabil, teknik pemotongan tidak sesuai, atau kondisi mekanisme mesin kurang baik.', 'Rapikan susunan material dan operasikan mesin secara stabil. Periksa mekanisme pemotongan dan pelumasan jika gerakan tetap berat.', 'Gunakan mesin dengan kedua tangan secara aman dan jauhkan tangan dari jalur pisau.', 'Data spesifikasi KS-AUV dan panduan pemeriksaan umum');
